final class TimelineCanvas:NSView {
    weak var editor:ProjectEditor?
    var envelopes=[String:[Float]]()
    func envelope(_ asset:[String:Any])->[Float] {
        guard let path=asset["path"] as? String else{return []};let key=path+":"+(asset["sha256"] as? String ?? "")
        if let cached=envelopes[key]{return cached}
        guard let f=try? AVAudioFile(forReading:URL(fileURLWithPath:path)),f.length>0,let buffer=AVAudioPCMBuffer(pcmFormat:f.processingFormat,frameCapacity:8192) else{return []}
        var bins=[Float](repeating:0,count:512);var offset:Int64=0
        do {while offset<f.length {try f.read(into:buffer,frameCount:AVAudioFrameCount(min(8192,f.length-offset)));guard buffer.frameLength>0,let channels=buffer.floatChannelData else{break}
            for i in 0..<Int(buffer.frameLength) {let bin=min(511,Int((offset+Int64(i))*512/f.length));for ch in 0..<Int(f.processingFormat.channelCount){bins[bin]=max(bins[bin],abs(channels[ch][i]))}}
            offset+=Int64(buffer.frameLength)
        }}catch{return []}
        envelopes[key]=bins;return bins
    }
    var dragRow:Int?;var dragX:CGFloat=0;var initialStart:Double=0
    override var isFlipped:Bool {true}
    func extent()->Double {max(10,(editor?.clips.map{($0["start"] as? Double ?? 0)+ProjectEditor.duration($0)}.max() ?? 10)+1)}
    override func draw(_ dirtyRect:NSRect) {
        NSColor.controlBackgroundColor.setFill();bounds.fill();guard let e=editor else{return}
        let scale=max(1,bounds.width-110)/extent();let roles=e.roles.map{$0["id"] as? String ?? ""}
        for i in 0...10 {let x=100+CGFloat(i)*(bounds.width-110)/10;NSColor.separatorColor.setStroke();let p=NSBezierPath();p.move(to:NSPoint(x:x,y:20));p.line(to:NSPoint(x:x,y:bounds.height));p.stroke();String(format:"%.1fs",Double(i)*extent()/10).draw(at:NSPoint(x:x,y:0),withAttributes:[.font:NSFont.systemFont(ofSize:10),.foregroundColor:NSColor.secondaryLabelColor])}
        for (i,r) in e.roles.enumerated() {(r["name"] as? String ?? "角色").draw(at:NSPoint(x:4,y:32+i*42),withAttributes:[.font:NSFont.systemFont(ofSize:12)])}
        for (i,c) in e.clips.enumerated() {
            let lane=roles.firstIndex(of:c["role_id"] as? String ?? "") ?? 0;let start=c["start"] as? Double ?? 0
            let rect=NSRect(x:100+start*scale,y:25+CGFloat(lane*42),width:max(12,ProjectEditor.duration(c)*scale),height:32)
            NSColor.systemTeal.withAlphaComponent(0.55).setFill();NSBezierPath(roundedRect:rect,xRadius:4,yRadius:4).fill()
            if i==e.selectedClip {NSColor.keyboardFocusIndicatorColor.setStroke();let p=NSBezierPath(rect:rect);p.lineWidth=2;p.stroke()}
            if let asset=c["audio"] as? [String:Any] {
                let bins=envelope(asset);let seconds=asset["seconds"] as? Double ?? 0
                if !bins.isEmpty,seconds>0 {
                    let lo=c["trim_in"] as? Double ?? 0;let duration=ProjectEditor.duration(c);let path=NSBezierPath();let width=max(1,Int(rect.width));let db=c["gain_db"] as? Double ?? 0
                    for pixel in 0..<width {let a=min(511,max(0,Int((lo+Double(pixel)/Double(width)*duration)/seconds*512)));let b=min(511,max(a,Int((lo+Double(pixel+1)/Double(width)*duration)/seconds*512)));let amplitude=min(1,Double(bins[a...b].max() ?? 0)*pow(10,db/20));let x=rect.minX+Double(pixel);path.move(to:NSPoint(x:x,y:rect.midY-amplitude*13));path.line(to:NSPoint(x:x,y:rect.midY+amplitude*13))}
                    NSColor.labelColor.withAlphaComponent(0.55).setStroke();path.lineWidth=1;path.stroke()
                }
            }
            let text=c["name"] as? String ?? "片段";text.draw(in:rect.insetBy(dx:4,dy:6),withAttributes:[.font:NSFont.systemFont(ofSize:11),.foregroundColor:NSColor.labelColor])
        }
    }
    override func mouseDown(with event:NSEvent) {
        guard let e=editor,e.owner.process==nil else{return};let p=convert(event.locationInWindow,from:nil);let scale=max(1,bounds.width-110)/extent();let ids=e.roles.map{$0["id"] as? String ?? ""}
        for (i,c) in e.clips.enumerated().reversed() {let lane=ids.firstIndex(of:c["role_id"] as? String ?? "") ?? 0;let rect=NSRect(x:100+(c["start"] as? Double ?? 0)*scale,y:25+CGFloat(lane*42),width:max(12,ProjectEditor.duration(c)*scale),height:32);if rect.contains(p){e.selectClip(i);dragRow=i;dragX=p.x;initialStart=c["start"] as? Double ?? 0;return}}
    }
    override func mouseUp(with event:NSEvent) {
        guard let e=editor,let i=dragRow,e.owner.process==nil else{return};defer{dragRow=nil};let x=convert(event.locationInWindow,from:nil).x;let value=max(0,min(3599,initialStart+Double(x-dragX)/(max(1,bounds.width-110)/extent())))
        e.change {var cs=e.clips;cs[i]["start"]=value;cs[i]["timing_manual"]=true;cs[i].removeValue(forKey:"timing_review_required");e.clips=cs;e.project.removeValue(forKey:"mixdown");e.project.removeValue(forKey:"chapter_mixdown")}
    }
    override func mouseDragged(with event:NSEvent) {needsDisplay=true}
}

final class UndoAudioLease {
    weak var editor:ProjectEditor?
    let id=UUID()
    init(editor:ProjectEditor,snapshot:[String:Any]){self.editor=editor;editor.retainUndoAudio(id,snapshot:snapshot)}
    func release(){editor?.releaseUndoAudio(id)}
    deinit{release()}
}

